    return sorted(vs, key=key)

def run_length_encode(s: str) -> str:
    """Compress runs of repeated characters as <char><count>. Single characters keep count 1."""
    if not s:
        return ""
    result = []
    count = 1
    prev = s[0]
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{prev}{count}")
            prev = ch
            count = 1
    result.append(f"{prev}{count}")
    return "".join(result)

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float."""
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    cleaned = s.replace('$', '').replace(',', '')
    if cleaned == '':
        raise ValueError("empty price string")
    try:
        return float(cleaned)
    except ValueError as e:
        raise ValueError(f"invalid price format: {s}") from e

def c_to_f(c: float) -> float:
    """Convert Celsius to Fahrenheit (F = C * 9/5 + 32), rounded to 1 decimal."""
    return round(c * 9 / 5 + 32, 1)

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result: list[int] = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def fizzbuzz(n: int) -> list:
    """Return the FizzBuzz strings for 1..n ('Fizz' for multiples of 3, 'Buzz' for 5, 'FizzBuzz' for both)."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

def normalize_phone(s: str) -> str:
    """Normalize a US phone number to the form (XXX) XXX-XXXX or XXX-XXX-XXXX if input had parentheses."""
    digits = ''.join(ch for ch in s if ch.isdigit())
    if len(digits) != 10:
        raise ValueError("Phone number must contain 10 digits")
    area, exchange, line = digits[:3], digits[3:6], digits[6:]
    has_parentheses = '(' in s or ')' in s
    if has_parentheses:
        return f"{area}-{exchange}-{line}"
    else:
        return f"({area}) {exchange}-{line}"

def is_palindrome(s: str) -> bool:
    """Return True if s reads the same forwards and backwards, ignoring case and non-alphanumeric characters."""
    if s is None:
        return False
    cleaned = [c.lower() for c in s if c.isalnum()]
    return cleaned == cleaned[::-1]

def valid_parens(s: str) -> bool:
    """Return True if every (, [, { is closed by the matching bracket in the right order."""
    stack = []
    match = {')': '(', ']': '[', '}': '{'}
    opens = set(match.values())
    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in match:
            if not stack or stack[-1] != match[ch]:
                return False
            stack.pop()
        else:
            # ignore other characters if any
            continue
    return not stack

def median(nums: list) -> float:
    """Return the median of a non‑empty list of numbers.
    For an odd length list, return the middle value.
    For an even length list, return the mean of the two middle values.
    The result is always a float.
    """
    if not nums:
        raise ValueError("median requires a non-empty list")
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_nums[mid])
    else:
        return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2.0

import csv
import os

def fx_rate(date: str) -> float:
    """Return the USD->EUR closing rate on the given date, read from data/ecb_rates_2019.csv."""
    # Path relative to this file
    path = os.path.join(os.path.dirname(__file__), '..', 'data', 'ecb_rates_2019.csv')
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row.get('date') == date:
                return float(row.get('rate'))
    raise ValueError(f"Date {date} not found in ecb_rates_2019.csv")
